const fs=require(''fs'');

// Complete function to update a single file
function updateFile(lang, forIOSData) {
  const f = lang + ''.json'';
  const d = JSON.parse(fs.readFileSync(f, ''utf8''));
  d.forIOS = forIOSData;
  fs.writeFileSync(f, JSON.stringify(d, null, 2), ''utf8'');
  return true;
}

